const CatalogManager = {
  getAll() { return ExtendedDressCatalog; },
  getBySku(sku) { return ExtendedDressCatalog.find(item => item.sku === sku); },
  filterByColor(color) { return ExtendedDressCatalog.filter(item => item.color.toLowerCase() === color.toLowerCase()); },
  filterByFabric(fabric) { return ExtendedDressCatalog.filter(item => item.fabric.toLowerCase() === fabric.toLowerCase()); }
};

if (typeof window !== 'undefined') { window.CatalogManager = CatalogManager; }
if (typeof module !== 'undefined' && module.exports) { module.exports = { CatalogManager, ExtendedDressCatalog }; }